import{_ as a,a as t,o as r,a4 as d}from"./chunks/framework.-FZumj2l.js";const u=JSON.parse('{"title":"Cancel Order","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-cancel-order","title":"Cancel Order","description":"Cancel every cancellable item on an order. Returns the updated order summary.","query":"mutation CancelOrder($input: createAdminCancelOrderInput!) {\\n  createAdminCancelOrder(input: $input) {\\n    adminCancelOrder {\\n      id\\n      orderId\\n      incrementId\\n      status\\n      statusLabel\\n      grandTotal\\n      success\\n      message\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"orderId\\": 2392\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createAdminCancelOrder\\": {\\n      \\"adminCancelOrder\\": {\\n        \\"id\\": \\"/api/admin/admin_cancel_orders/2392\\",\\n        \\"orderId\\": 2392,\\n        \\"incrementId\\": \\"2392\\",\\n        \\"status\\": \\"canceled\\",\\n        \\"statusLabel\\": \\"Canceled\\",\\n        \\"grandTotal\\": 219,\\n        \\"success\\": true,\\n        \\"message\\": \\"Order canceled successfully.\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/sales/orders/cancel.md","filePath":"api/graphql-api/admin/sales/orders/cancel.md","lastUpdated":1783327468000}'),n={name:"api/graphql-api/admin/sales/orders/cancel.md"};function o(c,e,s,i,l,p){return r(),t("div",null,e[0]||(e[0]=[d('<h1 id="cancel-order" tabindex="-1">Cancel Order <a class="header-anchor" href="#cancel-order" aria-label="Permalink to &quot;Cancel Order&quot;">​</a></h1><p>Cancels every cancellable item on an order. This is the same action as the <strong>Cancel</strong> button on the admin order-view screen, with the same eligibility gates as REST.</p><div class="tip custom-block"><p class="custom-block-title">GraphQL returns a summary; REST returns the full detail</p><p>The GraphQL mutation returns a slim order <strong>summary</strong> (<code>orderId</code>, <code>incrementId</code>, <code>status</code>, <code>statusLabel</code>, <code>grandTotal</code>, <code>success</code>, <code>message</code>). The REST endpoint (<code>POST /api/admin/orders/{id}/cancel</code>) returns the <strong>full</strong> updated order-detail payload. Use REST, or re-query <code>adminOrderDetail</code>, when you need the complete order after cancelling.</p></div><div class="tip custom-block"><p class="custom-block-title">Prerequisites</p><p>The example targets an order with cancellable items. Only orders that have <strong>not</strong> been invoiced or shipped can be canceled — once an order is invoiced (typically <code>processing</code>) it can only be <strong>refunded</strong>, and the mutation returns <em>&quot;This order has already been invoiced or shipped and can no longer be canceled. You can issue a refund instead.&quot;</em> Pick an order in <code>pending</code> state (nothing invoiced yet) to cancel.</p></div><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>createAdminCancelOrder</code></td><td>Mutation</td><td>Cancel an order</td></tr></tbody></table><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><p>Each failure returns the <code>errors[]</code> array with one of these messages:</p><table tabindex="0"><thead><tr><th>Condition</th><th>Lang key</th><th>Message</th></tr></thead><tbody><tr><td>Order is <code>closed</code></td><td><code>bagistoapi::app.admin.order.actions.cancel.closed</code></td><td>Closed orders cannot be canceled.</td></tr><tr><td>Order is <code>fraud</code></td><td><code>bagistoapi::app.admin.order.actions.cancel.fraud</code></td><td>Fraud orders cannot be canceled.</td></tr><tr><td>Order has invoiced / shipped items (e.g. <code>processing</code>)</td><td><code>bagistoapi::app.admin.order.actions.cancel.already-processed</code></td><td>This order has already been invoiced or shipped and can no longer be canceled. You can issue a refund instead.</td></tr><tr><td>No item has any quantity left to cancel</td><td><code>bagistoapi::app.admin.order.actions.cancel.nothing-to-cancel</code></td><td>There is nothing to cancel on this order.</td></tr><tr><td>Admin role lacks <code>sales.orders.cancel</code></td><td><code>bagistoapi::app.admin.order.actions.cancel.no-permission</code></td><td>You do not have permission to cancel orders.</td></tr></tbody></table>',9)]))}const m=a(n,[["render",o]]);export{u as __pageData,m as default};
